function gapPairs(nums: number[], k: number): number {
  const found = new Set<number>();
  for (let i = 0; i < nums.length; i++)
    for (let j = 0; j < nums.length; j++)
      if (i !== j && nums[j] - nums[i] === k) found.add(nums[i]);
  return found.size;
}

